from django.shortcuts import render
from django.http import JsonResponse
import os
import json

def index(request):
    return render(request, 'dashboard/index.html')

def api_data(request):
    # Path to the JSON file generated by main.py
    file_path = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(__file__))), 'dashboard_data.json')
    try:
        if os.path.exists(file_path):
            with open(file_path, 'r') as f:
                data = json.load(f)
            return JsonResponse(data)
        else:
            return JsonResponse({"error": "No data available yet. Please wait for the ML pipeline to initialize."}, status=404)
    except Exception as e:
        return JsonResponse({"error": str(e)}, status=500)
